  "lean_source": "import Std\n\nnamespace JoinContract\n\ninductive Mode where\n  | inner\n  | left\n  | full\n\ninductive JsonVal where\n  | null\n  | bool (b : Bool)\n  | num (n : Nat)\n  | str (s : String)\n  | arr (xs : List JsonVal)\n  | obj (m : List (String × JsonVal))\n\ndef keyEq (a b : JsonVal) : Bool :=\n  match a, b with\n  | .null, .null => false\n  | .bool a, .bool b => a == b\n  | .num a, .num b => a == b\n  | .str a, .str b => a == b\n  | .arr a, .arr b => a == b\n  | .obj a, .obj b => a == b\n  | _, _ => false\n\ndef getRowKey (row : List (String × JsonVal)) : JsonVal :=\n  match row with\n  | [] => .null\n  | (\"key\", v) :: _ => v\n  | _ :: rest => getRowKey rest\n  | _ => .null\n\ninductive JoinResult where\n  | pair (l r : List (String × JsonVal))\n  | leftOnly (l : List (String × JsonVal))\n  | rightOnly (r : List (String × JsonVal))\n\ndef solve (left right : List (List (String × JsonVal))) (key : String) (mode : Mode) : List JoinResult :=\n  let matches (l r : List (String × JsonVal)) : Bool :=\n    let kl := getRowKey l\n    let kr := getRowKey r\n    match kl, kr with\n    | .null, _ => false\n    | _, .null => false\n    | _, _ => keyEq kl kr\n  let rec go (ls : List (List (String × JsonVal))) (rs : List (List (String × JsonVal))) (acc : List JoinResult) : List JoinResult :=\n    match ls with\n    | [] =>\n      match mode with\n      | .full =>\n        let unmatchedRs := rs.filter (fun r => ls.all (fun l => !matches l r))\n        acc ++ unmatchedRs.map (fun r => .rightOnly r)\n      | _ => acc\n    | l :: rest =>\n      let matchedRs := rs.filter (fun r => matches l r)\n      let newAcc := acc ++ matchedRs.map (fun r => .pair l r)\n      let acc' := if matchedRs.isEmpty then newAcc ++ [.leftOnly l] else newAcc\n      go rest rs acc'\n  go left right []\n\ndef valid (left right : List (List (String × JsonVal))) (key : String) (mode : Mode) : Prop :=\n  True\n\ntheorem thm_join_correct (left right : List (List (String × JsonVal))) (key : String) (mode : Mode)\n    (h : valid left right key mode) :\n  ∀ (l r : List (String × JsonVal)),\n    (∃ (i j : Nat), left[i] =? l ∧ right[j] =? r ∧\n      (match mode with\n       | .inner => ∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .pair l r\n       | .left => (∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .pair l r) ∨\n                  (getRowKey l = .null → ∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .leftOnly l)\n       | .full => (∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .pair l r) ∨\n                  (getRowKey l = .null → ∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .leftOnly l))) ↔\n    (getRowKey l ≠ .null ∧ getRowKey r ≠ .null ∧ keyEq (getRowKey l) (getRowKey r)) := by sorry\n\ntheorem non_vacuity :\n  ∃ (left right : List (List (String × JsonVal))) (key : String) (mode : Mode),\n    valid left right key mode ∧\n    (∃ (l r : List (List (String × JsonVal))),\n      left = l :: _ ∧ right = r :: _ ∧\n      getRowKey l ≠ .null ∧ getRowKey r ≠ .null ∧\n      keyEq (getRowKey l) (getRowKey r) ∧\n      ∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .pair l r) ∧\n    (∃ (l : List (List (String × JsonVal))),\n      left = l :: _ ∧\n      getRowKey l ≠ .null ∧\n      (∀ (r : List (List (String × JsonVal))), right = r :: _ → !keyEq (getRowKey l) (getRowKey r)) ∧\n      (mode = .left ∨ mode = .full) ∧\n      ∃ (res : JoinResult), solve left right key mode = res :: _ ∧ res = .leftOnly l) := by sorry\n\nend JoinContract",
